function rowsOf(nodeName) {
  const root = $(nodeName).first()?.json ?? {};
  if (Array.isArray(root)) return root;
  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.items)) return root.items;
  if (Array.isArray(root.results)) return root.results;
  return [];
}
function contentId(row) {
  return String(row.content_id ?? row.contentId ?? row.video_id ?? row.videoId ?? row.contentID ?? row.id ?? '');
}
function competitorId(row) {
  return row.competitor_id ?? row.competitorId ?? row.competitor?.id ?? null;
}
function competitorName(row) {
  return String(row.competitor_name ?? row.competitorName ?? row.name ?? row.competitor?.name ?? 'Unknown competitor');
}
function toNum(v) {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
}

const contentRows = rowsOf('02 - Get Competitor Contents');
const analysisRows = rowsOf('03 - Get Content Analysis');
const metricRows = rowsOf('04 - Get Performance KPI');
if (!analysisRows.length) throw new Error('Không có Content Analysis. Hãy chạy WF03 trước và kiểm tra GET /api/ai-analysis.');

const contentById = new Map();
for (const c of contentRows) {
  const cid = contentId(c);
  if (cid) contentById.set(cid, c);
  if (c.id != null) contentById.set(String(c.id), c);
}
const metricsByContent = new Map();
for (const m of metricRows) {
  const cid = contentId(m);
  if (cid) metricsByContent.set(cid, m);
}

const now = Date.now();
const day = 24 * 60 * 60 * 1000;
const currentStart = now - 7 * day;
const previousStart = now - 14 * day;
const groups = new Map();
for (const a of analysisRows) {
  const topic = String(a.topic ?? a.name ?? a.category ?? '').trim();
  if (!topic) continue;
  const aid = String(a.content_id ?? a.contentId ?? a.video_id ?? a.videoId ?? a.social_content_id ?? a.id ?? '');
  const c = contentById.get(aid) ?? a;
  const cid = contentId(c) || aid;
  const dateValue = c.published_at ?? c.publishedAt ?? c.published_at ?? c.created_at ?? a.published_at ?? a.createdAt;
  const ts = dateValue ? new Date(dateValue).getTime() : NaN;
  const period = Number.isFinite(ts) && ts >= currentStart ? 'current' :
    (Number.isFinite(ts) && ts >= previousStart && ts < currentStart ? 'previous' : 'other');
  const m = metricsByContent.get(cid) ?? {};
  if (!groups.has(topic.toLowerCase())) groups.set(topic.toLowerCase(), {
    name: topic, current_count: 0, previous_count: 0, total_count: 0,
    total_views: 0, total_likes: 0, total_comments: 0, content_ids: [],
    competitors: new Set(), current_content_ids: [], previous_content_ids: []
  });
  const g = groups.get(topic.toLowerCase());
  g.total_count++;
  if (period === 'current') { g.current_count++; g.current_content_ids.push(cid); }
  if (period === 'previous') { g.previous_count++; g.previous_content_ids.push(cid); }
  g.total_views += toNum(m.views ?? c.views);
  g.total_likes += toNum(m.likes ?? c.likes);
  g.total_comments += toNum(m.comments ?? c.comments);
  if (cid) g.content_ids.push(cid);
  const comp = competitorId(c) ?? competitorId(a);
  if (comp != null) g.competitors.add(String(comp));
}
if (!groups.size) throw new Error('Không tìm thấy topic hợp lệ trong Content Analysis.');
const out = [];
for (const g of groups.values()) {
  const growth = g.previous_count > 0 ? Number((((g.current_count - g.previous_count) / g.previous_count) * 100).toFixed(2)) : null;
  const engagementRate = g.total_views > 0 ? Number((((g.total_likes + g.total_comments) / g.total_views) * 100).toFixed(2)) : 0;
  const growthDirection = growth === null ? (g.current_count > 0 ? 'emerging' : 'insufficient_data') : growth > 0 ? 'up' : growth < 0 ? 'down' : 'stable';
  const evidence = [...new Set(g.content_ids)].slice(0, 12);
  const data = {
    name: g.name, current_count: g.current_count, previous_count: g.previous_count,
    total_count: g.total_count, growth_rate: growth, direction: growthDirection,
    competitor_count: g.competitors.size, total_views: g.total_views,
    engagement_rate: engagementRate, evidence,
    ai_prompt: `You are an evidence-based social media competitive trend analyst.

LANGUAGE:
- Write reason and trend_summary in Vietnamese.
- Return exactly one valid JSON object.
- Do not use Markdown code fences.
- Do not include any text outside the JSON object.

OUTPUT FORMAT:
{
  "score": 0,
  "direction": "insufficient_data",
  "reason": "Giải thích ngắn gọn dựa trên dữ liệu được cung cấp.",
  "trend_summary": "Tóm tắt xu hướng trong một câu."
}

RULES:
1. Analyze only the supplied metrics. Never invent facts or missing values.
2. direction must be exactly one of:
   "up", "down", "stable", "emerging", "insufficient_data".
3. If growth_rate is null, the historical baseline is insufficient.
   Do not claim that the trend is increasing or decreasing based only on total_views.
   If current_count > 0, direction may be "emerging" only when the data supports identifying newly observed content; otherwise use "insufficient_data".
4. If growth_rate is a number:
   - Positive growth_rate means "up".
   - Negative growth_rate means "down".
   - Zero growth_rate means "stable".
   Use the counts and metrics to explain the result without exaggerating.
5. Score must be an integer from 0 to 100.
   The score represents the strength of the evidence for a trend, not simply the number of views.
   When historical data is insufficient, use a conservative score and explain the limitation.
6. Do not claim that views, likes, comments, or engagement increased or decreased unless the supplied data supports that comparison.
7. Keep reason concise and trend_summary to one sentence.

DATA:
${JSON.stringify({
  name: g.name,
  current_count: g.current_count,
  previous_count: g.previous_count,
  total_count: g.total_count,
  growth_rate: growth,
  direction: growthDirection,
  competitor_count: g.competitors.size,
  total_views: g.total_views,
  engagement_rate: engagementRate,
  evidence
})}`
  };
  out.push({json:data});
}
return out;

function parseAI(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value === 'string') {
    const t = value.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
    return JSON.parse(t);
  }
  throw new Error('AI Trend Analysis không trả về JSON.');
}
const aiItems = $input.all();
const source = $('05 - Aggregate Topics').all();
return aiItems.map((item, i) => {
  const base = source[i]?.json;
  if (!base) throw new Error(`Không tìm thấy dữ liệu topic gốc tại vị trí ${i}`);
  const root = item.json;
  const txt =
  root.content?.parts?.[0]?.text ??
  root.content ??
  root.output?.[0]?.content?.[0]?.text ??
  root.output?.[0]?.content?.text ??
  root.text ??
  root.message?.content;
  const ai = parseAI(txt);
  const fallback = base.current_count > 0 ? 55 : 30;
  const score = Math.round(Math.max(0, Math.min(100, Number(ai.score ?? fallback))));
  return {json: {
    name: base.name,
    score,
    growth_rate: base.growth_rate ?? 0,
    direction: String(ai.direction ?? base.direction),
    reason: String(ai.reason ?? ai.trend_summary ?? 'Phân tích dựa trên số lượng nội dung, mức tăng trưởng và tương tác.'),
    evidence: base.evidence,
    detected_at: new Date().toISOString(),
    current_count: base.current_count,
    previous_count: base.previous_count,
    competitor_count: base.competitor_count,
    engagement_rate: base.engagement_rate,
    is_valid:
  Boolean(base.name) &&
  !['n/a', 'na', 'unknown', 'untitled'].includes(
    String(base.name).trim().toLowerCase()
  ) &&
  Number.isFinite(score) &&
  score >= 0 &&
  score <= 100 &&
  Array.isArray(base.evidence) &&
  base.evidence.length > 0
  }};
});
